def transform(grid):
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        color = row[0]
        if color == background:
            continue
        last = max(i for i, x in enumerate(row) if x == color)
        for c in range(last + 1, len(row)):
            if row[c] == background:
                out[r][c] = 1
    return out

